func TestCreateDAG_ConcurrentSafety(t *testing.T) {
	consumer := &MEGAccessConsumer{}

	// 创建有效的DAG配置
	validConfig := &dag.DAGConfig{
		DAGName: global.TaskComeNewAuditStartTPDagName,
		Head: dag.DAGNode{
