	mockStartDag.On("StartDag", mock.Anything, global.TaskComeNewAuditStartTPDagName, mock.Anything, mock.Anything, global.TaskComeAK, global.TaskComeSK).
		Return(nil).Times(10) // 期望调用10次
	GlobalStartDagFunc = mockStartDag.StartDag
	defer func() { GlobalStartDagFunc = originalStartDagFunc }()

	// 并发测试
	const numGoroutines = 10
	errors := make(chan error, numGoroutines)

	for i := 0; i < numGoroutines; i++ {
		go func(index int) {
			params := &global.TaskComeRequest{
				TraceID: fmt.Sprintf("concurrent-test-%d", index),
				PlanID:  fmt.Sprintf("plan_%d", index),
			}
			err := consumer.createDAG(context.Background(), params)
			errors <- err
		}(i)
	}

	// 收集结果
	for i := 0; i < numGoroutines; i++ {
		err := <-errors
		assert.NoError(t, err)
	}

	// 验证mock调用
	mockStartDag.AssertExpectations(t)
}
