func TestMEGAccessConsumer_ParseRequest(t *testing.T) {
	if os.Getenv("RUN_MANUAL_TESTS") != "true" {
		t.Skip("手动测试未启用，设置 RUN_MANUAL_TESTS=true 来执行")
	}
	tests := []struct {
		name     string
		rawJSON  string
		wantErr  bool
		validate func(t *testing.T, req *global.TaskComeRequest)
	}{
		{
			name: "正常JSON解析",
			rawJSON: `{
				"trace_id": "test_trace_123",
				"store_id": 123456789,
				"poi_name": "测试POI",
				"address": "测试地址",
				"city": "测试城市",
				"submit_to": {
					"poi_name": "提交POI",
					"address": "提交地址",
					"phone": ["010-12345678"],
					"cood_sys": "bd09ll",
					"point": "116.308420,40.056750",
					"city": "北京市"
				}
			}`,
			wantErr: false,
			validate: func(t *testing.T, req *global.TaskComeRequest) {
				if req.TraceID != "test_trace_123" {
					t.Errorf("期望的TraceID为 'test_trace_123', 实际为 %s", req.TraceID)
				}
				if req.StoreID != 123456789 {
					t.Errorf("期望的StoreID为 123456789, 实际为 %d", req.StoreID)
				}
				if req.PoiName != "提交POI" {
					t.Errorf("期望的PoiName为 '提交POI', 实际为 %s", req.PoiName)
				}
			},
		},
		{
			name:     "无效JSON",
			rawJSON:  `{invalid json}`,
			wantErr:  true,
			validate: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			consumer := &MEGAccessConsumer{ctx: context.Background()}

			req, err := consumer.parseRequest([]byte(tt.rawJSON))

			if (err != nil) != tt.wantErr {
				t.Errorf("parseRequest() error = %v, wantErr %v", err, tt.wantErr)
				return
			}

			if !tt.wantErr && tt.validate != nil {
				tt.validate(t, req)
			}
		})
	}
}

