import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"sync"
)

type DAGConfig struct {
	DAGName string         `json:"dag_name"`
	Nodes   map[string]int `json:"-"`
	Head    DAGNode        `json:"head"`
}
type DAGNode struct {
	TaskName string    `json:"task_name"`
	NodeID   int       `json:"node_id"`
	ParentID int       `json:"parent_id"`
	Children []DAGNode `json:"children"`
}

var (
	dagConfigs  = make(map[string]*DAGConfig)
	configMutex sync.RWMutex
)

func LoadDAGConfigs(configDir string) error {
	files, err := filepath.Glob(filepath.Join(configDir, "*.json"))
	if err != nil {
		return err
	}

	for _, file := range files {
		content, err := os.ReadFile(file)
		if err != nil {
			return err
		}

		var config DAGConfig
		if err := json.Unmarshal(content, &config); err != nil {
			return err
		}

		// 构建节点映射
		config.Nodes = make(map[string]int)
		buildNodeMap(&config.Head, config.Nodes)

		dagConfigs[config.DAGName] = &config
	}

	return nil
}

func buildNodeMap(node *DAGNode, nodeMap map[string]int) {
	// 使用完整路径作为key，格式为: parent_node_id/task_name
	key := node.TaskName
	if node.ParentID != 0 {
		key = fmt.Sprintf("%d/%s", node.ParentID, node.TaskName)
	}
	nodeMap[key] = node.NodeID

	for _, child := range node.Children {
		child.ParentID = node.NodeID // 设置子节点的ParentID
		buildNodeMap(&child, nodeMap)
	}
}

func GetNodeID(dagName, taskName string) (int, bool) {
	if config, ok := dagConfigs[dagName]; ok {
		nodeID, exists := config.Nodes[taskName]
		return nodeID, exists
	}
	return 0, false
}

func GetDAGConfig(dagName string) (*DAGConfig, bool) {
	configMutex.RLock()
	defer configMutex.RUnlock()
	config, exists := dagConfigs[dagName]
	return config, exists
}

// GetNextNode 获取指定节点的下一个节点ID
func GetNextNode(dagName, nodeFrom, taskName string) (string, error) {
	config, exists := GetDAGConfig(dagName)
	if !exists {
		return "", fmt.Errorf("DAG配置不存在: %s", dagName)
	}

	// 如果是起始节点，直接使用head的子节点
	if nodeFrom == "" {
		for _, child := range config.Head.Children {
			if child.TaskName == taskName {
				return strconv.Itoa(child.NodeID), nil
			}
		}
		return "", fmt.Errorf("起始节点的子服务不存在: 目标服务=%s", taskName)
	}

	// 转换节点ID格式
	currentNodeID, err := strconv.Atoi(nodeFrom)
	if err != nil {
		return "", fmt.Errorf("无效的当前节点ID: %s", nodeFrom)
	}

	// 如果当前节点就是head节点
	if config.Head.NodeID == currentNodeID {
		for _, child := range config.Head.Children {
			if child.TaskName == taskName {
				return strconv.Itoa(child.NodeID), nil
			}
		}
		return "", fmt.Errorf("head节点的子服务不存在: 目标服务=%s", taskName)
	}

	// 查找非head节点的直接子节点
	var currentNode *DAGNode
	var findNode func(node *DAGNode) bool

	findNode = func(node *DAGNode) bool {
		if node.NodeID == currentNodeID {
			currentNode = node
			return true
		}
		for i := range node.Children {
			if findNode(&node.Children[i]) {
				return true
			}
		}
		return false
	}

	// 在整个DAG中查找指定节点
	if !findNode(&config.Head) {
		return "", fmt.Errorf("当前节点不存在于DAG中: %s", nodeFrom)
	}

	// 检查直接子节点
	for _, child := range currentNode.Children {
		if child.TaskName == taskName {
			return strconv.Itoa(child.NodeID), nil
		}
	}

	return "", fmt.Errorf("当前节点的子服务不存在: 当前节点=%s, 目标服务=%s", nodeFrom, taskName)
}

func GetAllDAGConfigs() map[string]*DAGConfig {
	configMutex.RLock()
	defer configMutex.RUnlock()

	// 返回配置的深拷贝
	copy := make(map[string]*DAGConfig)
	for k, v := range dagConfigs {
		copy[k] = v
	}
	return copy
}

