func DiffReqInfoData(ctx context.Context, req *global.TaskComeRequest) (global.TaskComeDataParam, error) {

	logger := log.Init{
		Ctx: ctx,
	}
	logger.Notice("DiffReqInfoData start", req)
	taskcomeData := global.TaskComeDataParam{
		Status:    int64(taskcome.ResultRunFailStatus),
		Result:    "default fail",
		StopFlow:  1,
		NextNodes: "",
	}
	// req.StoreID转字符串
	tid := fmt.Sprintf("%d", req.StoreID)
	name := req.SubmitTo.PoiName
	// req.StoreID转字符串
	//address := req.SubmiTo.Address
	tidMap := map[string]bool{}
	results, err := query.GetDataByName(name)
	//nextNodes := global.TaskComeNodeID[global.TaskComeNewAuditStartTPDagName][""]
	if err != nil {
		// 查询失败
		//msg := "[diff数据]\n读取tp数据库失败，GetDataByName err\nid:" + tid + "\nerr:" + err.Error() + "\n"
		//utils.SendMsgToHi(msg, global.MenuAlarmAtUsersAuditResult)
		taskcomeData.Result = "GetDataByName err " + err.Error()
		return taskcomeData, err
	}
	if len(results) > 0 {
		for i := range results {
			tidMap[results[i].Tid] = true
		}
		for _, item := range results {
			if item.ReqID != req.ReqID {
				continue
			}
			//判断需求id是否为meg,暂时不需要
			//判断地址是否相同 名称地址相同 且tid不在tidList 且没入库不需要处理
			if item.Address == req.SubmitTo.Address && !(tidMap[tid]) && req.ReqID == item.ReqID {
				taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
				req.StepRes.ResMsg = "相同名称地址的tid存在多个"
				req.StepRes.ResStatus = global.StatusDiffSameNameAddr
				nextNodes, err := dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, "operator_final_callback")
				if err != nil {
					logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for same name addr path", logit.Error("err", err))
					return global.TaskComeDataParam{}, err
				}
				taskcomeData = taskcomeutil.MakeTaskComeData(ctx, *req, 0,
					nextNodes, int64(taskcome.ResultRunSuccessStatus))
				return taskcomeData, nil
			}
		}

	}

	result, err := query.GetDataByID(tid, int(req.ReqID))
	if err != nil {
		// 查询失败
		//msg := "[diff数据]\n读取tp数据库失败，GetDataByName err\nid:" + tid + "\nerr:" + err.Error() + "\n"
		//utils.SendMsgToHi(msg, global.MenuAlarmAtUsersAuditResult)
		taskcomeData.Result = "GetDataByID err " + err.Error()
		return taskcomeData, err
	}
	nextNodes, err := dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, "operator_panchong")
	if err != nil {
		logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for main path", logit.Error("err", err))
		return global.TaskComeDataParam{}, err
	}

	if result.ID == 0 {
		// 插入数据表
		taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
		req.StepRes.ResStatus = global.StatusDiffNew
		req.StepRes.ResMsg = "提交数据为新数据"
		taskcomeData = taskcomeutil.MakeTaskComeData(ctx, *req, 0,
			nextNodes, int64(taskcome.ResultRunSuccessStatus))
		return taskcomeData, err
	} else if dataDiff(result, *req) {
		// 更新数据表 待编写
		taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
		req.StepRes.ResStatus = global.StatusDiffNoDiff
		req.StepRes.ResMsg = "本次提交数据与历史数据完全一致"
		err := query.UpdateAliveTime(global.RequestInfoIDMEG, tid) // 后续改为通用的
		if err != nil {
			taskcomeData.Result = "UpdateAliveTime err " + err.Error()
			return taskcomeData, err
		}
		taskcomeData = taskcomeutil.MakeTaskComeData(ctx, *req, 0,
			nextNodes, int64(taskcome.ResultRunSuccessStatus))
		return taskcomeData, err
	}
	taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
	req.StepRes.ResStatus = global.StatusDiffUpdate
	req.StepRes.ResMsg = "提交数据存在，但是信息变更，需要更新数据"
	taskcomeData = taskcomeutil.MakeTaskComeData(ctx, *req, 0,
		nextNodes, int64(taskcome.ResultRunSuccessStatus))
	return taskcomeData, err
}

func dataDiff(tpDataStorage entity.TpDataStorage, req global.TaskComeRequest) bool {
	// 将tpDataStorage的PointX、PointY进行拼接
	point := tpDataStorage.PointX + "," + tpDataStorage.PointY
	//  将tpDataStorage的Phone解析为字符串列表
	phoneList := []string{}
	if tpDataStorage.Phone != "" {
		phoneList = strings.Split(tpDataStorage.Phone, ",")
	}
	if tpDataStorage.Name == req.SubmitTo.PoiName &&
		tpDataStorage.Address == req.SubmitTo.Address &&
		point == req.SubmitTo.Point &&
		req.SubmitTo.BusinessTime == tpDataStorage.ShopHours &&
		EqualStringSetIgnoreDup(phoneList, req.SubmitTo.Phone) {
		return true
	}
	return false

}

func EqualStringSetIgnoreDup(a, b []string) bool {
	setA := make(map[string]struct{})
	setB := make(map[string]struct{})

	for _, v := range a {
		setA[v] = struct{}{}
	}
	for _, v := range b {
		setB[v] = struct{}{}
	}

	if len(setA) != len(setB) {
		return false
	}

	for k := range setA {
		if _, ok := setB[k]; !ok {
			return false
		}
	}
	return true
}

