		point == req.SubmitTo.Point &&
		req.SubmitTo.BusinessTime == tpDataStorage.ShopHours &&
		EqualStringSetIgnoreDup(phoneList, req.SubmitTo.Phone) {
		return true
	}
	return false

}

func EqualStringSetIgnoreDup(a, b []string) bool {
	setA := make(map[string]struct{})
	setB := make(map[string]struct{})

	for _, v := range a {
		setA[v] = struct{}{}
	}
	for _, v := range b {
		setB[v] = struct{}{}
	}

	if len(setA) != len(setB) {
		return false
	}

	for k := range setA {
		if _, ok := setB[k]; !ok {
			return false
		}
	}
	return true
}

