// ProcessSingle 处理单条数据（流式处理入口）
func (p *PanchongProcessor) ProcessSingle(ctx context.Context, req *global.TaskComeRequest) (*PanchongResult, error) {
	result := &PanchongResult{
		Success:      true,
		ErrCode:      ErrorCodeSuccess,
		ErrMsg:       "",
		InnerErrMsg:  "",
		GStatus:      GlStatusAdd,
		GBid:         "1",
