		PointY:       "",
		RelatedList:  make([]RelatedItem, 0),
		OriginalData: *req.SubmitTo,
		FixedData:    *req.SubmitTo,
	}

	// 第一步：数据规范化处理（对应Python中的NormalizationOperator）
	if err := p.processNormalization(ctx, req); err != nil {
		result.Success = false
		result.ErrCode = ErrorCodeFail
		result.ErrMsg = "数据规范化失败"
		result.InnerErrMsg += err.Error() + ";"
		return result, nil
	}

	// 第二步：地址格式化（对应Python中的format_address）
	if err := p.processAddressFormat(ctx, req, result); err != nil {
		result.Success = false
		result.ErrCode = ErrorCodeFail
		result.ErrMsg = "地址格式化失败"
		result.InnerErrMsg += err.Error() + ";"
		return result, nil
	}

	// 第三步：判重处理（对应Python中的panchong_service_*方法）
	if err := p.processPanchong(ctx, req, result); err != nil {
		result.Success = false
		result.ErrCode = ErrorCodeFail
		result.ErrMsg = "判重处理失败:" + err.Error()
		result.InnerErrMsg += err.Error()
		return result, nil
	}

	return result, nil
}

