		}
		data := res
		contentRaw, ok := data["content"]
		if ok {
			content, ok := contentRaw.(map[string]interface{})
			if ok {
				req.GlBidINFO.ID, _ = content["bid"].(string)
				req.GlBidINFO.Name, _ = content["name"].(string)
				req.GlBidINFO.PointX, _ = content["point_x"].(string)
				req.GlBidINFO.PointY, _ = content["point_y"].(string)
				req.GlBidINFO.City, _ = content["city_name"].(string)
				req.GlBidINFO.Status, _ = content["point_y"].(string)
				req.GlBidINFO.AreaName, _ = content["area_name"].(string)
				req.GlBidINFO.StdTag, _ = content["std_tag"].(string)
