// panchongServiceCommon 通用判重服务
func (p *PanchongProcessor) panchongServiceCommon(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	// 转换数据结构
	row := p.convertReqToRow(req)

	// 获取源类型
	srcType := req.PanChongSrcType
	if p.serviceConfig.RequestInfoID == "1204" && srcType == "" {
		srcType = "tp_meg"
	}

	// 打包数据
	packData := p.panchongPack(row, 0, srcType) // 非TP判重

	// 调用服务 - 使用RAL服务调用方式（参考GetPointByAddress）
	response, err := p.callPanchongService(ctx, packData)
	if err != nil {
		result.GStatus = GlStatusAdd
		return nil
	}

	// 处理响应
	glBid := response.GlBid
	if glBid == 0 {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBidStr := p.stringifyInterface(glBid)
	if glBidStr != "0" && glBidStr != "1" { // 关联
		result.GStatus = GlStatusGL
		result.GBid = glBidStr
		return nil
	}

	if glBidStr == "1" { // 新增
		result.GStatus = GlStatusAdd
	} else if glBidStr == "0" { // 疑似关联
		result.GStatus = GlStatusNotSure
		result.RelatedList = make([]RelatedItem, 0)

		// if list, ok := response["list"].([]interface{}); ok {

		for _, outItem := range response.List {
			for _, inItem := range outItem.List {
				relatedItem := RelatedItem{
					RelatedBid: p.stringifyInterface(inItem.RelateBid),
					Confidence: p.stringifyInterface(inItem.LstmGbdtScore),
				}
				result.RelatedList = append(result.RelatedList, relatedItem)
			}

		}
	}

	return nil
}

// callPanchongService 调用判重服务（参考GetPointByAddress的RAL调用方式）
func (p *PanchongProcessor) callPanchongService(ctx context.Context, packData PanchongPackRequest) (PanchongPackResponse, error) {

	if err := codeconv.EncodeStruct("gb18030", &packData); err != nil {
		return PanchongPackResponse{}, err
	}

	fmt.Println("packData:", packData)

	// 创建RAL请求
	ralReq := &nshead.RalRequest{
		Encoder: codec.MCPACKEncoder,
		Body:    packData,
	}

	res := PanchongPackResponse{}
	ralRes := &nshead.RalResponse{
		Decoder: codec.MCPACKDecoder,
		Data:    &res,
	}

	// 调用RAL服务
	if err := ral.RAL(ctx, global.PanchongNormalServiceName, ralReq, ralRes); err != nil {
		return PanchongPackResponse{}, err
	}

	return res, nil
}

