// panchongServiceCommonTP 通用+TP判重（默认方式）
func (p *PanchongProcessor) panchongServiceCommonTP(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	// 重置BID
	result.GBid = ""

	// 前序步骤出错
	if result.ErrCode != "0" {
		// 模拟Python中的fail_cnt计数，这里简单跳过
		return nil
	}

	// 转换数据结构
	row := p.convertReqToRow(req)

	// 获取源类型
	srcType := p.serviceConfig.PanchongSrcType
	if p.serviceConfig.RequestInfoID == "1204" && srcType == "" {
		srcType = "tp_meg"
	}

	// 先进行非TP判重
	packData := p.panchongPack(row, 0, srcType) // 非TP判重

	// 将结构体转换为map，兼容retryFrameHTTP
	packDataMap := p.convertPanchongPackToMap(packData)

	// 调用服务 - 简化实现
	response, err := p.retryFrameHTTP(ctx, "", packDataMap, nil, "errno", true, "lianzhi_log.txt")
	if err != nil {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBid, exists := response["gl_bid"]
	if !exists {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBidStr := p.stringifyInterface(glBid)

	// 检查是否关联
	if glBidStr != "0" && glBidStr != "1" { // 关联
		result.GStatus = GlStatusGL
		result.GBid = glBidStr
		return nil
	}

	// 非关联，尝试TP判重
	packData = p.panchongPack(row, 1, srcType) // TP判重

	// 将结构体转换为map，兼容retryFrameHTTP
	packDataMap = p.convertPanchongPackToMap(packData)

	response, err = p.retryFrameHTTP(ctx, "", packDataMap, nil, "errno", true, "lianzhi_log.txt")
	if err != nil {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBid, exists = response["gl_bid"]
	if !exists {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBidStr = p.stringifyInterface(glBid)

	// 再次检查关联状态
	if glBidStr != "0" && glBidStr != "1" { // TP关联
		result.GStatus = GlStatusGL
		result.GBid = glBidStr
		result.RelatedList = []RelatedItem{
			{RelatedBid: glBidStr, Confidence: "0.8"},
		}
		return nil
	}

	// 非关联，获取候选列表
	relateBidDict := make(map[string]float64)
	if list, ok := response["list"].([]interface{}); ok {
		for _, itemOut := range list {
			if outerMap, ok := itemOut.(map[string]interface{}); ok {
				if innerList, ok := outerMap["list"].([]interface{}); ok {
					for _, itemIn := range innerList {
						if innerMap, ok := itemIn.(map[string]interface{}); ok {
							bid := p.stringifyInterface(innerMap["relate_bid"])
							scoreStr := p.stringifyInterface(innerMap["name_score"])
							if score, err := strconv.ParseFloat(scoreStr, 64); err == nil {
								relateBidDict[bid] = score
							}
						}
					}
				}
			}
		}
	}

	// 排序获取前3
	var relateBidList []RelatedItem
	for bid, score := range relateBidDict {
		relateBidList = append(relateBidList, RelatedItem{
			RelatedBid: bid,
			Confidence: strconv.FormatFloat(score, 'f', 5, 64),
		})
	}

	// 简化排序 - 实际需要按分数倒序
	if len(relateBidList) == 0 {
		result.GStatus = GlStatusAdd
	} else {
		result.GStatus = GlStatusNotSure
		// 取前3个
		if len(relateBidList) > 3 {
			result.RelatedList = relateBidList[:3]
		} else {
			result.RelatedList = relateBidList
		}
	}

	return nil
}

// panchongServiceAsHash 仅as_hash判重
func (p *PanchongProcessor) panchongServiceAsHash(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	row := p.convertReqToRow(req)
	packData := p.asPanchongPack(row)

	// 简化调用
	response, err := p.retryFrameHTTP(ctx, "", packData, nil, "errno", true, "lianzhi_log.txt")
	if err != nil {
		result.GStatus = GlStatusAdd
		return nil
	}

	if succCnt, ok := response["succ_cnt"].(float64); ok && int(succCnt) != 1 {
		result.GStatus = GlStatusAdd
		return nil
	}

	if list, ok := response["list"].([]interface{}); !ok || len(list) == 0 {
		result.GStatus = GlStatusAdd
		return nil
	}

	result.GStatus = GlStatusNotSure
	result.RelatedList = make([]RelatedItem, 0)

	if list, ok := response["list"].([]interface{}); ok {
		for _, item := range list {
			if itemMap, ok := item.(map[string]interface{}); ok {
				relatedItem := RelatedItem{
					RelatedBid: p.stringifyInterface(itemMap["relate_bid"]),
					Confidence: p.stringifyInterface(itemMap["lstm_gbdt_score"]),
				}
				result.RelatedList = append(result.RelatedList, relatedItem)
			}
		}
	}

	return nil
}

