// panchongPack 通用判重数据封装
func (p *PanchongProcessor) panchongPack(row map[string]interface{}, recallType int, srcType string) PanchongPackRequest {
	pointX := ""
	pointY := ""

	// 提取数据
	data, _ := row["data"].(map[string]interface{})
	fixed, _ := row["fixed"].(map[string]interface{})

	if data != nil {
		if rawX, ok := data["raw_point_x"]; ok {
			if tx, ok := rawX.(float64); ok {
				pointX = strconv.FormatFloat(tx, 'f', -1, 64)
			} else if strX, ok := rawX.(string); ok {
				pointX = strX
			}
		}
		if rawY, ok := data["raw_point_y"]; ok {
			if ty, ok := rawY.(float64); ok {
				pointY = strconv.FormatFloat(ty, 'f', -1, 64)
			} else if strY, ok := rawY.(string); ok {
				pointY = strY
			}
		}
	}

	name := ""
	if data != nil {
		if n, ok := data["name"]; ok {
			name = n.(string)
		}
	}

	address := ""
	city := ""
	if fixed != nil {
		if addr, ok := fixed["fix_address"]; ok {
			address = addr.(string)
		}
		if c, ok := fixed["fix_city"]; ok {
			city = c.(string)
		}
	}

	return PanchongPackRequest{
		Type:        16,
		RetNum:      3,
		LinkingType: 1,
		RecallType:  recallType,
		List: []PanchongItem{
			{
				ID:               "12345",
				PointX:           pointX,
				PointY:           pointY,
				Name:             name,
				Address:          address,
				Phone:            "",
				Tag:              "",
				City:             city,
				Src:              "",
				SrcType:          srcType,
				SignboardFeature: "",
			},
		},
	}
}

// asPanchongPack AS_HASH判重数据封装
