// Helper methods
func (p *PanchongProcessor) convertToProcessRequest(req *global.TaskComeRequest) *data_plugin.ProcessRequest {
	processReq := &data_plugin.ProcessRequest{
		PoiName: req.SubmitTo.PoiName,
		Address: req.SubmitTo.Address,
		City:    req.SubmitTo.City,
		Phone:   req.SubmitTo.Phone,
		Point:   req.SubmitTo.Point,
	}

	// 解析坐标点
	if req.SubmitTo.Point != "" {
		parts := strings.Split(req.SubmitTo.Point, ",")
		if len(parts) == 2 {
			fmt.Sscanf(parts[0], "%f", &processReq.PointX)
			fmt.Sscanf(parts[1], "%f", &processReq.PointY)
		}
	}

	return processReq
}

