func (p *PanchongProcessor) processAddressFormat(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	// 准备请求参数
	ID := fmt.Sprintf("%d", req.StoreID)
	formatReq := &data_plugin.AddressFormatRequest{
		ID:      ID,
		Name:    req.SubmitTo.PoiName,
		Address: req.SubmitTo.Address,
		City:    req.SubmitTo.City,
	}
	point := req.SubmitTo.MktPoint
	if point != "" {
		formatReq.PointX = strings.Split(point, ",")[0]
		formatReq.PointY = strings.Split(point, ",")[1]
	}

	// 特殊业务线处理
	if req.ReqID == global.RequestInfoIDMEG {
		formatReq.BizLine = "tp_meg"
	}

	// 调用地址格式化服务
	err := data_plugin.FormatAddress(ctx, req, formatReq)
	if err != nil {
		return fmt.Errorf("address format service error: %v", err)
	}

	return nil
}

// processPanchong 判重处理
func (p *PanchongProcessor) processPanchong(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	if result.ErrCode != ErrorCodeSuccess {
		return nil
	}
	result.GBid = "1"
	if req.ReqID == global.RequestInfoIDMEG && !req.GeoRight {
		result.GStatus = GlStatusAdd
		return nil
	}
	var pcErr error
	// 根据配置选择判重方式
	switch p.config.PanchongWay {
	case "common":
		//return p.panchongServiceCommon(ctx, req, result)
		pcErr = p.panchongServiceCommon(ctx, req, result)
	case "common+baozhun":
		//return p.panchongServiceCommonBaozhun(ctx, req, result)
		return p.panchongServiceCommon(ctx, req, result)
	case "common+TP":
		//p.panchongServiceCommonTP(ctx, req, result)
		pcErr = p.panchongServiceCommon(ctx, req, result)
	case "as_hash":
		//p.panchongServiceAsHash(ctx, req, result)
		pcErr = p.panchongServiceCommon(ctx, req, result)
	case "common+as_hash":
		//p.panchongServiceCommonAsHash(ctx, req, result)
		pcErr = p.panchongServiceCommon(ctx, req, result)
	default:
		// 无默认
		pcErr = fmt.Errorf("unknown panchong way: %s", p.config.PanchongWay)
	}
	if pcErr != nil {
		return pcErr
	}
	if req.ReqID == 1204 && result.GStatus != GlStatusGL {
		err := p.panchongServiceAsHashRecall(ctx, req, result)
		if err != nil {
			return err
		}
	}
	// if row["gl_status"] != "gl" and (
	// 	"point_x" not in row or "point_y" not in row
	// ):
	// 	row["err_code"] = "3"  # 未关联且无坐标，标记为失败
	// 	row["err_msg"] = "地址不规范"
	if result.GStatus != GlStatusGL && req.SubmitTo.Point == "" {
		return fmt.Errorf("坐标不规范")
	}
	if result.GStatus == GlStatusGL {
		res, err := GetBasicInfo(ctx, result.GBid)
		if err != nil {
			return err
		}
		data := res
		contentRaw, ok := data["content"]
		if ok {
			content, ok := contentRaw.(map[string]interface{})
			if ok {
				req.GlBidINFO.ID, _ = content["bid"].(string)
				req.GlBidINFO.Name, _ = content["name"].(string)
				req.GlBidINFO.PointX, _ = content["point_x"].(string)
				req.GlBidINFO.PointY, _ = content["point_y"].(string)
				req.GlBidINFO.City, _ = content["city_name"].(string)
				req.GlBidINFO.Status, _ = content["point_y"].(string)
				req.GlBidINFO.AreaName, _ = content["area_name"].(string)
				req.GlBidINFO.StdTag, _ = content["std_tag"].(string)
				req.GlBidINFO.Address, _ = content["address"].(string)
			}
		}

	}

	return nil
}

// panchongServiceCommon 通用判重服务
func (p *PanchongProcessor) panchongServiceCommon(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	// 转换数据结构
	row := p.convertReqToRow(req)

	// 获取源类型
	srcType := req.PanChongSrcType
	if p.serviceConfig.RequestInfoID == "1204" && srcType == "" {
		srcType = "tp_meg"
	}

	// 打包数据
	packData := p.panchongPack(row, 0, srcType) // 非TP判重

	// 调用服务 - 使用RAL服务调用方式（参考GetPointByAddress）
	response, err := p.callPanchongService(ctx, packData)
	if err != nil {
		result.GStatus = GlStatusAdd
		return nil
	}

	// 处理响应
	glBid := response.GlBid
	if glBid == 0 {
		result.GStatus = GlStatusAdd
		return nil
	}

	glBidStr := p.stringifyInterface(glBid)
	if glBidStr != "0" && glBidStr != "1" { // 关联
		result.GStatus = GlStatusGL
		result.GBid = glBidStr
		return nil
	}

	if glBidStr == "1" { // 新增
		result.GStatus = GlStatusAdd
	} else if glBidStr == "0" { // 疑似关联
		result.GStatus = GlStatusNotSure
		result.RelatedList = make([]RelatedItem, 0)

		// if list, ok := response["list"].([]interface{}); ok {

		for _, outItem := range response.List {
			for _, inItem := range outItem.List {
				relatedItem := RelatedItem{
					RelatedBid: p.stringifyInterface(inItem.RelateBid),
					Confidence: p.stringifyInterface(inItem.LstmGbdtScore),
				}
				result.RelatedList = append(result.RelatedList, relatedItem)
			}

		}
	}

	return nil
}

// callPanchongService 调用判重服务（参考GetPointByAddress的RAL调用方式）
func (p *PanchongProcessor) callPanchongService(ctx context.Context, packData PanchongPackRequest) (PanchongPackResponse, error) {

	if err := codeconv.EncodeStruct("gb18030", &packData); err != nil {
		return PanchongPackResponse{}, err
	}

	fmt.Println("packData:", packData)

	// 创建RAL请求
	ralReq := &nshead.RalRequest{
		Encoder: codec.MCPACKEncoder,
		Body:    packData,
	}

	res := PanchongPackResponse{}
	ralRes := &nshead.RalResponse{
		Decoder: codec.MCPACKDecoder,
		Data:    &res,
	}

	// 调用RAL服务
	if err := ral.RAL(ctx, global.PanchongNormalServiceName, ralReq, ralRes); err != nil {
		return PanchongPackResponse{}, err
	}

	return res, nil
}

// panchongServiceCommonBaozhun 通用+保准判重
func (p *PanchongProcessor) panchongServiceCommonBaozhun(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	// TODO: 先调用通用判重
	err := p.panchongServiceCommon(ctx, req, result)
