	}

	// 如果不是通用关联，再进行as_hash判重
	if result.GStatus != GlStatusGL {
		return p.panchongServiceAsHash(ctx, req, result)
	}

	return nil
}

// panchongServiceAsHashRecall 新版AS_HASH判重服务
func (p *PanchongProcessor) panchongServiceAsHashRecall(ctx context.Context, req *global.TaskComeRequest, result *PanchongResult) error {
	var srcType string
	if req.PanChongSrcType != "" {
		srcType = req.PanChongSrcType
	} else {
		srcType = "tp_meg"
	}

	// 打包数据
	packData := p.asNewPanchongPack(req, srcType)

	// 调用服务 - 使用RAL服务调用方式（参考panchongServiceCommon）
	response, err := p.callAsHashService(ctx, packData)
	if err != nil {
		return err
	}

	// 处理响应
	glBid := response.Data.GlBid
	switch glBid {
	case "1":
		result.GStatus = GlStatusAdd
	case "0":
		result.GStatus = GlStatusNotSure
	default:
		if len(glBid) > 1 {
			result.GStatus = GlStatusGL
			result.GBid = glBid
		}
	}

	return nil
}

