// PanchongResponse 判重服务响应结构
type PanchongResponse struct {
	Errno   int32                `json:"errno"`
	GlBid   interface{}          `json:"gl_bid"` // 可能是string或int
	List    []PanchongInnerItem  `json:"list"`
	SuccCnt int32                `json:"succ_cnt"`
	Data    *PanchongNewResponse `json:"data"`
}

type PanchongInnerItem struct {
	List []PanchongDetailItem `json:"list"`
}

type PanchongDetailItem struct {
	RelateBid     interface{} `json:"relate_bid"`
	NameScore     interface{} `json:"name_score"`
	LstmGBDTScore interface{} `json:"lstm_gbdt_score"`
}

type PanchongNewResponse struct {
	GlBid interface{} `json:"gl_bid"`
}

// panchongPack 通用判重数据封装
func (p *PanchongProcessor) panchongPack(row map[string]interface{}, recallType int, srcType string) PanchongPackRequest {
	pointX := ""
	pointY := ""

	// 提取数据
	data, _ := row["data"].(map[string]interface{})
	fixed, _ := row["fixed"].(map[string]interface{})

	if data != nil {
		if rawX, ok := data["raw_point_x"]; ok {
			if tx, ok := rawX.(float64); ok {
				pointX = strconv.FormatFloat(tx, 'f', -1, 64)
			} else if strX, ok := rawX.(string); ok {
				pointX = strX
			}
		}
		if rawY, ok := data["raw_point_y"]; ok {
			if ty, ok := rawY.(float64); ok {
				pointY = strconv.FormatFloat(ty, 'f', -1, 64)
			} else if strY, ok := rawY.(string); ok {
				pointY = strY
			}
		}
	}

	name := ""
	if data != nil {
		if n, ok := data["name"]; ok {
			name = n.(string)
		}
	}

	address := ""
	city := ""
	if fixed != nil {
		if addr, ok := fixed["fix_address"]; ok {
			address = addr.(string)
		}
		if c, ok := fixed["fix_city"]; ok {
			city = c.(string)
		}
	}

	return PanchongPackRequest{
		Type:        16,
		RetNum:      3,
		LinkingType: 1,
		RecallType:  recallType,
		List: []PanchongItem{
			{
				ID:               "12345",
				PointX:           pointX,
				PointY:           pointY,
				Name:             name,
				Address:          address,
				Phone:            "",
				Tag:              "",
				City:             city,
				Src:              "",
				SrcType:          srcType,
				SignboardFeature: "",
			},
		},
	}
}

// asPanchongPack AS_HASH判重数据封装
func (p *PanchongProcessor) asPanchongPack(row map[string]interface{}) map[string]interface{} {
	data, _ := row["data"].(map[string]interface{})
	fixed, _ := row["fixed"].(map[string]interface{})

	name := ""
	if data != nil {
		if n, ok := data["name"]; ok {
			name = n.(string)
		}
	}

	city := ""
	address := ""
	if fixed != nil {
		if c, ok := fixed["fix_city"]; ok {
			city = c.(string)
		}
		if addr, ok := fixed["fix_address"]; ok {
			address = addr.(string)
		}
	}

	return map[string]interface{}{
		"type":       15,
		"ret_num":    3,
		"confidence": 2.0,
		"list": []map[string]interface{}{
			{
				"id":      12345,
				"name":    name,
				"city":    city,
				"address": address,
			},
		},
	}
}

// asNewPanchongPack 新版AS_HASH判重数据封装
func (p *PanchongProcessor) asNewPanchongPack(req *global.TaskComeRequest, srcType string) AsHashPanchongRequest {
	pointXStr := ""
	pointYStr := ""
	if req.SubmitTo.Point != "" {
		parts := strings.Split(req.SubmitTo.Point, ",")
		pointXStr, pointYStr = parts[0], parts[1]
	}

	if pointXStr == "" || pointYStr == "" {
		return AsHashPanchongRequest{}
	}

	// 将字符串坐标转换为float64
	pointX, err := strconv.ParseFloat(pointXStr, 64)
	if err != nil {
		return AsHashPanchongRequest{}
	}
	pointY, err := strconv.ParseFloat(pointYStr, 64)
	if err != nil {
		return AsHashPanchongRequest{}
	}

	name := req.SubmitTo.PoiName
	id := fmt.Sprintf("%s", req.StoreID)

	city := req.SubmitTo.FixCity
	address := req.SubmitTo.FixAddress
	return AsHashPanchongRequest{
		ReqType: 66,
		LogID:   id,
		PoiInfo: AsHashPoiInfo{
			UID:     id,
			Name:    name,
			City:    city,
			Address: address,
			PointX:  pointX,
			PointY:  pointY,
			SrcType: srcType,
		},
	}
}

// convertReqToRow 将TaskComeRequest转换为字典格式，便于判重服务处理
func (p *PanchongProcessor) convertReqToRow(req *global.TaskComeRequest) map[string]interface{} {
	data := map[string]interface{}{
		"name": req.SubmitTo.PoiName,
		"id":   req.ID,
	}

	// 解析坐标
	if req.SubmitTo.Point != "" {
		parts := strings.Split(req.SubmitTo.Point, ",")
		if len(parts) == 2 {
			data["raw_point_x"] = parts[0]
			data["raw_point_y"] = parts[1]
		}
	}

	fixed := map[string]interface{}{
		"fix_address": req.SubmitTo.FixAddress,
		"fix_city":    req.SubmitTo.FixCity,
	}

	if req.SubmitTo.Address != "" {
		fixed["fix_address"] = req.SubmitTo.Address
	}
	if req.SubmitTo.City != "" {
		fixed["fix_city"] = req.SubmitTo.City
	}

	return map[string]interface{}{
		"data":    data,
		"fixed":   fixed,
		"point_x": data["raw_point_x"],
		"point_y": data["raw_point_y"],
	}
}

// convertPanchongPackToMap 将PanchongPackRequest转换为map[string]interface{}
func (p *PanchongProcessor) convertPanchongPackToMap(packData PanchongPackRequest) map[string]interface{} {
	packDataMap := map[string]interface{}{
		"type":         packData.Type,
		"ret_num":      packData.RetNum,
		"linking_type": packData.LinkingType,
		"recall_type":  packData.RecallType,
	}

	// 转换列表项
	list := make([]map[string]interface{}, len(packData.List))
	for i, item := range packData.List {
		list[i] = map[string]interface{}{
			"id":                item.ID,
			"point_x":           item.PointX,
			"point_y":           item.PointY,
			"name":              item.Name,
			"address":           item.Address,
			"phone":             item.Phone,
			"tag":               item.Tag,
			"city":              item.City,
			"src":               item.Src,
			"src_type":          item.SrcType,
			"signboard_feature": item.SignboardFeature,
		}
	}
	packDataMap["list"] = list

	return packDataMap
}

// callAsHashService 调用新版AS_HASH判重服务（参考callPanchongService的RAL调用方式）
func (p *PanchongProcessor) callAsHashService(ctx context.Context, packData AsHashPanchongRequest) (AsHashPanchongResponse, error) {
	ralReq := &ghttp.RalPostRequest{
		Encoder: codec.JSONEncoder,
	}
	ralReq.Header = http.Header{}
	ralReq.Header.Set("Content-Type", "application/json")
	ralReq.Path = "/new-chain-service/chain/lsbt"
	ralReq.PostData = packData

	res := AsHashPanchongResponse{}
	ralRes := &ghttp.RalResponse{
		Data:    &res, // 这里需要传递指针，使JSON反序列化能正常工作
		Decoder: codec.JSONDecoder,
	}

	// 调用RAL服务 - 使用新版AS_HASH服务名称
	if err := ral.RAL(ctx, global.ASHashServiceName, ralReq, ralRes); err != nil {
		return AsHashPanchongResponse{}, err
	}

	return res, nil
}

// stringifyInterface 安全字符串转换接口类型
func (p *PanchongProcessor) stringifyInterface(val interface{}) string {
	switch v := val.(type) {
	case string:
		return v
	case int, int32, int64:
		return strconv.FormatInt(v.(int64), 10)
	case float32, float64:
		return strconv.FormatFloat(v.(float64), 'f', -1, 64)
	case uint64:
		return strconv.FormatUint(v, 10)
	default:
		return ""
	}
}

func GetBasicInfo(ctx context.Context, bid string) (map[string]any, error) {
	// python 代码     request_url = 'http://{}:{}/Query/query?id={}&targent={}&source=poi_xy_aoi'.format(ip, port, bid, card_name)
	// request_url = 'http://{}:{}/Query/query?id={}&targent={}&source=poi_xy_aoi'.format(ip, port, bid, card_name)
	// 测试
	// http://10.94.198.225:8006/Query/query?id=526341950419743832&targent=basic:content.area_name,content.city_name,content.address,content.name&source=poi_xy_aoi
	cardName := fmt.Sprintf("basic")

	params := url.Values{}
	params.Add("id", bid)
	params.Add("targent", cardName)
	params.Add("source", global.BasicInfoSource)

	// header := make(http.Header)
	// header.Set("Content-Type", "application/json")

	request := &ghttp.RalRequest{
		Method: "GET",
		Path:   global.BasicInfoPath,
		Query:  params,
		// Header: header,
	}

	poi := make(map[string]any)

	response := &ghttp.RalResponse{}
	ralErr := ral.RAL(ctx, "poi_storage_proxy", request, response)
	if ralErr != nil {
		return poi, ralErr
	}
	rawResp := response.Response()
	if rawResp == nil {
		rErr := errors.New("table response is nil")
		return poi, rErr
	}

	respData, respErr := io.ReadAll(rawResp.Body)
	if respErr != nil {
		return poi, respErr
	}
	defer rawResp.Body.Close()

	fmt.Println(string(respData))

	var resp global.POIBasicInfoResp
	jErr := json.Unmarshal(respData, &resp)
	if jErr != nil {
		return poi, jErr
	}

	if len(resp.Data) == 0 {
		return poi, errors.New("no data")
	}

	jErr = json.Unmarshal([]byte(resp.Data[0]), &poi)
	if jErr != nil {
		return poi, jErr
	}
	return poi, nil
}

// PanChongReqInfoData 判重数据处理入口（流式处理）
func PanChongReqInfoData(ctx context.Context, req *global.TaskComeRequest) (global.TaskComeDataParam, error) {
	logger := log.Init{
		Ctx: ctx,
	}
	logger.Notice("PanChongReqInfoData start", req)

	taskcomeData := global.TaskComeDataParam{
		Status:    int64(0),
		Result:    "default fail",
		StopFlow:  1,
		NextNodes: "",
	}

	// 1. 创建判重处理器
	processor := NewPanchongProcessor(req.PanChongWay, req.PanChongSrcType)

	// 2. 执行判重流程
	result, err := processor.ProcessSingle(ctx, req)
	if err != nil {
		// logger.Error("Panchong processing error", err)
		taskcomeData.Result = "判重处理失败: " + err.Error()
		return taskcomeData, err
	}

	// 3. 更新TaskComeRequest中的提交数据（流式处理结果反馈）
	req.SubmitTo = &result.FixedData

	// 4. 根据判重结果设置不同的状态和下一步节点
	if result.Success {
		taskcomeData.Status = int64(0)
		var nextNodes string
		// 根据判重状态确定下一步流程
		switch result.GStatus {
		case GlStatusGL:
			taskcomeData.Result = "关联成功，关联BID: " + result.GBid
			nextNodes, err := dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeMTONodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for GL status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为关联成功数据"
			req.StepRes.ResStatus = global.StepStatusPCGL
			taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
			taskcomeData = taskcomeutil.MakeTaskComeDataForMultiToOne(ctx, *req, 0, nextNodes, int64(taskcome.ResultRunSuccessStatus))
			return taskcomeData, err
		case GlStatusAdd:
			taskcomeData.Result = "新增POI，需要人工审核"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeQualityChackNodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for Add status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为新增POI数据"
			req.StepRes.ResStatus = global.StepStatusPCAdd
		case GlStatusNotSure:
			taskcomeData.Result = "疑似关联，需要确认"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeQualityChackNodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for NotSure status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为疑似关联数据"
			req.StepRes.ResStatus = global.StepStatusPCNotSure
		default:
			taskcomeData.Result = "判重处理失败"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, "")
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for default path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为判重处理数据"
			req.StepRes.ResStatus = global.StepStatusPCFail
		}

		taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
		taskcomeData = taskcomeutil.MakeTaskComeData(ctx, *req, 0,
			nextNodes, int64(taskcome.ResultRunSuccessStatus))
		logger.Notice("PanChongReqInfoData completed", taskcomeData)
		return taskcomeData, err
	} else {
		taskcomeData.Result = "判重失败: " + result.ErrMsg
		logger.Notice("PanChongReqInfoData fail", taskcomeData)
		return taskcomeData, err
	}
}

