					RelatedBid: p.stringifyInterface(itemMap["relate_bid"]),
					Confidence: p.stringifyInterface(itemMap["lstm_gbdt_score"]),
				}
				result.RelatedList = append(result.RelatedList, relatedItem)
			}
		}
	}

	return nil
}

