// PanChongReqInfoData 判重数据处理入口（流式处理）
func PanChongReqInfoData(ctx context.Context, req *global.TaskComeRequest) (global.TaskComeDataParam, error) {
	logger := log.Init{
		Ctx: ctx,
	}
	logger.Notice("PanChongReqInfoData start", req)

	taskcomeData := global.TaskComeDataParam{
		Status:    int64(0),
		Result:    "default fail",
		StopFlow:  1,
		NextNodes: "",
	}

	// 1. 创建判重处理器
	processor := NewPanchongProcessor(req.PanChongWay, req.PanChongSrcType)

	// 2. 执行判重流程
	result, err := processor.ProcessSingle(ctx, req)
	if err != nil {
		// logger.Error("Panchong processing error", err)
		taskcomeData.Result = "判重处理失败: " + err.Error()
		return taskcomeData, err
	}

	// 3. 更新TaskComeRequest中的提交数据（流式处理结果反馈）
	req.SubmitTo = &result.FixedData

	// 4. 根据判重结果设置不同的状态和下一步节点
	if result.Success {
		taskcomeData.Status = int64(0)
		var nextNodes string
		// 根据判重状态确定下一步流程
		switch result.GStatus {
		case GlStatusGL:
			taskcomeData.Result = "关联成功，关联BID: " + result.GBid
			nextNodes, err := dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeMTONodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for GL status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为关联成功数据"
			req.StepRes.ResStatus = global.StepStatusPCGL
			taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
			taskcomeData = taskcomeutil.MakeTaskComeDataForMultiToOne(ctx, *req, 0, nextNodes, int64(taskcome.ResultRunSuccessStatus))
			return taskcomeData, err
		case GlStatusAdd:
			taskcomeData.Result = "新增POI，需要人工审核"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeQualityChackNodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for Add status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为新增POI数据"
			req.StepRes.ResStatus = global.StepStatusPCAdd
		case GlStatusNotSure:
			taskcomeData.Result = "疑似关联，需要确认"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, global.TaskComeQualityChackNodeName)
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for NotSure status path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为疑似关联数据"
			req.StepRes.ResStatus = global.StepStatusPCNotSure
		default:
			taskcomeData.Result = "判重处理失败"
			nextNodes, err = dag.GetNextNode(global.TaskComeNewAuditStartTPDagName, req.NodeIDTo, "")
			if err != nil {
				logger.Warning(global.LOG_ERROR_CODE_WARNING, "failed to get next node for default path", logit.Error("err", err))
				return global.TaskComeDataParam{}, err
			}
			req.StepRes.ResMsg = "提交数据为判重处理数据"
			req.StepRes.ResStatus = global.StepStatusPCFail
		}

		taskcomeData.Status = int64(taskcome.ResultRunSuccessStatus)
